import { isBase32Array } from "./lib/Base32.js";
import { getFingerprintChar, getFingerprintIndex } from "./lib/characters.js";
import { fingerprintToHash, hashToFingerprint } from "./lib/codec.js";
import digest from "./lib/utils/digest.js";
import getUTF8StringLength from "./lib/utils/getUTF8StringLength.js";
import splitGraphemeString from "./lib/utils/splitGraphemeString.js";
import isString from "./lib/utils/isString.js";
import stringToUint8Array from "./lib/utils/stringToUint8Array.js";
export const fromFingerprintDisplay = (fingerprintDisplay) => {
    if (isFingerprintDisplay(fingerprintDisplay) === false) {
        throw new Error("Invalid FingerprintDisplay");
    }
    const characters = splitGraphemeString(fingerprintDisplay);
    return characters.map(char => getFingerprintIndex(char));
};
export const isFingerprint = (value) => {
    return isBase32Array(value) && value.length > 0;
};
export const uint8ArrayToFingerprint = async (uint8Array) => {
    const hash = await digest(uint8Array);
    return hashToFingerprint(hash);
};
export const publicKeyToFingerprint = async (publicKey) => {
    return await uint8ArrayToFingerprint(publicKey);
};
export const idToFingerprint = async (id) => {
    const uint8Array = stringToUint8Array(id);
    return await uint8ArrayToFingerprint(uint8Array);
};
export const fingerprintToUint8Array = (fingerprint) => {
    if (isFingerprint(fingerprint) === false) {
        throw new Error("Invalid Fingerprint");
    }
    return fingerprintToHash(fingerprint);
};
export const getFingerprintLength = (fingerprint) => {
    if (!isFingerprint(fingerprint)) {
        throw new Error("Invalid Fingerprint");
    }
    return fingerprint.length;
};
export const getFingerprintDisplayLength = (fingerprintDisplay) => {
    if (!isFingerprintDisplay(fingerprintDisplay)) {
        throw new Error("Invalid FingerprintDisplay");
    }
    return getUTF8StringLength(fingerprintDisplay);
};
export const compareFingerprints = (a, b) => {
    if (a.length !== b.length)
        return false;
    for (let i = 0; i < a.length; i++) {
        if (a[i] !== b[i])
            return false;
    }
    return true;
};
export const fingerprintStartsWith = (fingerprint, partialFingerprint) => {
    if (partialFingerprint.length > fingerprint.length)
        return false;
    for (let i = 0; i < partialFingerprint.length; i++) {
        if (fingerprint[i] !== partialFingerprint[i])
            return false;
    }
    return true;
};
export const fingerprintDisplayStartsWith = (fingerprintDisplay, partialFingerprintDisplay) => {
    const fingerprint = fromFingerprintDisplay(fingerprintDisplay);
    const partialFingerprint = fromFingerprintDisplay(partialFingerprintDisplay);
    return fingerprintStartsWith(fingerprint, partialFingerprint);
};
export const sliceFingerprint = (fingerprint, length) => {
    if (!isFingerprint(fingerprint)) {
        throw new Error("Invalid Fingerprint");
    }
    if (length === undefined) {
        return fingerprint;
    }
    return fingerprint.slice(0, length);
};
export const sliceFingerprintDisplay = (fingerprintDisplay, length) => {
    const fingerprint = fromFingerprintDisplay(fingerprintDisplay);
    const slicedFingerprint = sliceFingerprint(fingerprint, length);
    return displayFingerprint(slicedFingerprint);
};
export const isFingerprintDisplay = (value) => {
    if (isString(value) === false)
        return false;
    try {
        const characters = splitGraphemeString(value);
        characters.map(char => getFingerprintIndex(char));
        return true;
    }
    catch {
        return false;
    }
};
export const displayFingerprint = (fingerprint) => {
    return fingerprint.map((index) => getFingerprintChar(index)).join("");
};
export const normalizeFingerprintDisplay = (fingerprintDisplay) => {
    try {
        return displayFingerprint(fromFingerprintDisplay(fingerprintDisplay));
    }
    catch {
        throw new Error("Invalid FingerprintDisplay");
    }
};
export const isNormalizedFingerprintDisplay = (fingerprintDisplay) => {
    return fingerprintDisplay === normalizeFingerprintDisplay(fingerprintDisplay);
};
